begin;
do $$
declare teacher uuid:='11111111-1111-4111-8111-111111111111';other_teacher uuid:='22222222-2222-4222-8222-222222222222';candidate jsonb;pending jsonb;ready jsonb;rotation jsonb;old_ref text;
begin
 if has_table_privilege('anon','private.repolight_managed_connections','SELECT') or has_table_privilege('authenticated','private.repolight_managed_connections','SELECT') or has_table_privilege('service_role','private.repolight_managed_connections','SELECT') then raise exception 'Direct credential access granted';end if;
 if has_function_privilege('anon','public.read_repolight_managed_connection_v1(uuid,text)','EXECUTE') or has_function_privilege('authenticated','public.activate_repolight_managed_connection_v1(uuid,jsonb,text)','EXECUTE') then raise exception 'Browser registry RPC granted';end if;
 if not has_function_privilege('service_role','public.read_repolight_managed_connection_v1(uuid,text)','EXECUTE') then raise exception 'Service registry RPC missing';end if;
 candidate:=jsonb_build_object('teacherId',teacher,'tenantRef','opaque-tenant-1','operationRef',gen_random_uuid(),'keyId',gen_random_uuid(),'secretHash',repeat('a',64),'connectionRef','connection-1','apiOrigin','https://reports.example.test','installationRef','installation-1','encryptedKey',jsonb_build_object('version',1,'keyId','key-1','iv','opaque','tag','opaque','ciphertext','encrypted'),'operationKind','provision','expectedKeyId',null,'state','pending','workspaceRef',null);
 pending:=public.prepare_repolight_managed_connection_v1(teacher,candidate);
 if pending is distinct from candidate then raise exception 'Candidate changed';end if;
 if public.prepare_repolight_managed_connection_v1(teacher,candidate||jsonb_build_object('operationRef',gen_random_uuid(),'keyId',gen_random_uuid())) is distinct from pending then raise exception 'Duplicate intent replaced saved key';end if;
 if public.read_repolight_managed_connection_v1(other_teacher,'connection-1') is not null then raise exception 'Foreign teacher credential disclosed';end if;
 update private.registry_test_access set allowed=false;
 begin perform public.activate_repolight_managed_connection_v1(teacher,pending,'workspace-1');raise exception 'Expired provisioning activated';exception when insufficient_privilege then null;end;
 if public.read_repolight_managed_connection_v1(teacher)->>'state'<>'pending' then raise exception 'Denied activation modified pending row';end if;
 update private.registry_test_access set allowed=true;
 ready:=public.activate_repolight_managed_connection_v1(teacher,pending,'workspace-1');
 if ready->>'state'<>'ready' then raise exception 'Activation missing';end if;
 if public.activate_repolight_managed_connection_v1(teacher,pending,'workspace-1') is distinct from ready then raise exception 'Activation replay changed';end if;
 begin perform public.activate_repolight_managed_connection_v1(teacher,pending,'wrong-workspace');raise exception 'Workspace overwrite allowed';exception when invalid_parameter_value then null;end;
 old_ref:=ready->>'connectionRef';
 rotation:=ready||jsonb_build_object('operationKind','rotate','expectedKeyId',ready->>'keyId','operationRef',gen_random_uuid(),'keyId',gen_random_uuid(),'connectionRef','connection-rotated','state','pending');
 update private.registry_test_access set allowed=false;
 rotation:=public.prepare_repolight_managed_rotation_v1(teacher,rotation);
 if public.read_repolight_managed_connection_v1(teacher) is distinct from rotation then raise exception 'Pending rotation was hidden';end if;
 if public.read_repolight_managed_connection_v1(teacher,old_ref) is distinct from ready then raise exception 'Old cleanup locator lost';end if;
 if public.prepare_repolight_managed_rotation_v1(teacher,rotation||jsonb_build_object('operationRef',gen_random_uuid())) is distinct from rotation then raise exception 'Rotation retry replaced identity';end if;
 ready:=public.activate_repolight_managed_connection_v1(teacher,rotation,'workspace-1');
 if ready->>'state'<>'ready' or public.read_repolight_managed_connection_v1(teacher,old_ref)->>'state'<>'retired' then raise exception 'Rotation history missing';end if;
 if (select count(*) from private.repolight_managed_connections where teacher_id=teacher)<>2 then raise exception 'Credential history lost';end if;
 update private.registry_test_access set allowed=true;
 begin perform public.activate_repolight_managed_connection_v1(teacher,pending,'workspace-1');raise exception 'Retired key reactivated';exception when no_data_found then null;end;
 begin perform public.prepare_repolight_managed_rotation_v1(teacher,rotation||jsonb_build_object('operationRef',gen_random_uuid(),'keyId',gen_random_uuid(),'connectionRef','third'));raise exception 'Stale expectedKeyId accepted';exception when invalid_parameter_value then null;end;
 update private.registry_test_access set allowed=true;
 candidate:=candidate||jsonb_build_object('teacherId',other_teacher,'tenantRef','opaque-tenant-2','operationRef',gen_random_uuid(),'keyId',gen_random_uuid(),'connectionRef','other-teacher');
 pending:=public.prepare_repolight_managed_connection_v1(other_teacher,candidate);
 begin perform public.activate_repolight_managed_connection_v1(other_teacher,pending,'workspace-1');raise exception 'Cross-teacher workspace accepted';exception when invalid_parameter_value then null;end;
end $$;
rollback;
